<?php
require_once __DIR__ . '/../verifica_sessao.php'; require_admin();
require_once __DIR__ . '/../pdo.php'; require_once __DIR__ . '/../utils.php';
require_once __DIR__ . '/../models/RelatorioFinanceiro.php';
$ano = $_GET['ano'] ?? date('Y'); if(!preg_match('/^\d{4}$/',$ano)) $ano=date('Y');
$diario=RelatorioFinanceiro::porPeriodo($pdo,$ano.'-01-01',$ano.'-12-31');
$meses=[]; for($m=1;$m<=12;$m++){$k=sprintf('%s-%02d',$ano,$m);$meses[$k]=['entradas'=>0,'saidas_caixa'=>0,'saidas_nao_caixa'=>0,'cartao'=>0,'total'=>0,'faturamento'=>0];}
foreach($diario as $data=>$l){$k=substr($data,0,7);foreach($meses[$k] as $c=>$v)$meses[$k][$c]+=(float)$l[$c];}
$totais=RelatorioFinanceiro::totais($meses);
$nomes=[1=>'Janeiro','Fevereiro','Marco','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="financeiro-'.$ano.'.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,['Mes','Entradas','Saidas caixa','Saidas nao caixa','Cartao','Total','Faturamento'],';','"','');foreach($meses as $k=>$l)fputcsv($o,[$nomes[(int)substr($k,5,2)],number_format($l['entradas'],2,',','.'),number_format($l['saidas_caixa'],2,',','.'),number_format($l['saidas_nao_caixa'],2,',','.'),number_format($l['cartao'],2,',','.'),number_format($l['total'],2,',','.'),number_format($l['faturamento'],2,',','.')],';','"','');fclose($o);exit;}
include __DIR__.'/layout.php';
?>
