<div class="rf-cards"><?php foreach(['entradas'=>'Entradas','saidas_caixa'=>'Saidas caixa','saidas_nao_caixa'=>'Saidas nao caixa','cartao'=>'Total cartao','total'=>'Total','faturamento'=>'Faturamento anual'] as $c=>$r):?><div class="rf-card"><span><?=e($r)?></span><strong>R$ <?=number_format($totais[$c],2,',','.')?></strong></div><?php endforeach;?></div>
<div class="rf-tabela"><table><thead><tr><th>Mes</th><th>Entradas</th><th>Saidas caixa</th><th>Saidas nao caixa</th><th>Cartao</th><th>Total</th><th>Faturamento</th><th></th></tr></thead><tbody><?php foreach($meses as $k=>$l):?><tr><td><?=e($nomes[(int)substr($k,5,2)])?></td><td>R$ <?=number_format($l['entradas'],2,',','.')?></td><td>R$ <?=number_format($l['saidas_caixa'],2,',','.')?></td><td>R$ <?=number_format($l['saidas_nao_caixa'],2,',','.')?></td><td>R$ <?=number_format($l['cartao'],2,',','.')?></td><td>R$ <?=number_format($l['total'],2,',','.')?></td><td>R$ <?=number_format($l['faturamento'],2,',','.')?></td><td><a href="financeiro_mensal.php?mes=<?=e($k)?>">Ver dias</a></td></tr><?php endforeach;?><tr class="total"><td>Total do ano</td><?php foreach(['entradas','saidas_caixa','saidas_nao_caixa','cartao','total','faturamento'] as $c):?><td>R$ <?=number_format($totais[$c],2,',','.')?></td><?php endforeach;?><td></td></tr></tbody></table></div></div></div></div></div></body></html>
